'use client';
import React, { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import { BlogPost } from '@/data/blogData';
import AnimatedHeading from '@/components/AnimatedHeading';

import BlogCard from '@/components/BlogCard';

export default function BlogListingClient({ blogPosts }: { blogPosts: BlogPost[] }) {
  const [selectedCategory, setSelectedCategory] = useState('All');
  const sectionRef = useRef<HTMLDivElement>(null);

  const categories = ['All', 'Investment Guide', 'Market Analysis', 'Visa & Legal'];

  const filteredPosts = selectedCategory === 'All'
    ? blogPosts
    : blogPosts.filter(p => p.category === selectedCategory);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const cards = entry.target.querySelectorAll('.blog-card');
            cards.forEach((card, i) => {
              setTimeout(() => {
                (card as HTMLElement).style.opacity = '1';
                (card as HTMLElement).style.transform = 'translateY(0)';
              }, i * 120);
            });
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1 }
    );
    if (sectionRef.current) observer.observe(sectionRef.current);
    return () => observer.disconnect();
  }, [selectedCategory]);

  return (
    <section
      ref={sectionRef}
      style={{
        backgroundColor: '#ffffff',
        padding: 'clamp(100px, 12vw, 160px) clamp(20px, 5vw, 80px) clamp(60px, 8vw, 120px)'
      }}
    >
      <div style={{ maxWidth: '1320px', margin: '0 auto' }}>
        
        {/* Header Title */}
        <AnimatedHeading
          text="WeNest Journal"
          style={{
            fontFamily: 'Uxum Grotesque Regular, sans-serif',
            fontSize: 'clamp(40px, 8vw, 112px)',
            letterSpacing: 'clamp(-2px, -0.6vw, -6.8px)',
            lineHeight: '1em',
            color: '#02042d',
            margin: '0 0 clamp(16px, 2vw, 24px) 0',
            fontWeight: 400
          }}
        />

        {/* Subtitle */}
        <h2 style={{
          fontFamily: 'Uxum Grotesque Regular, sans-serif',
          fontSize: 'clamp(20px, 3vw, 36px)',
          fontWeight: 400,
          color: '#555555',
          lineHeight: 1.2,
          maxWidth: '900px',
          marginBottom: 'clamp(40px, 5vw, 60px)'
        }}>
          Expert guides, strategic market insights, and regulatory updates curated for international property investors in Dubai.
        </h2>

        {/* Category Filters */}
        <div style={{
          display: 'flex',
          gap: '8px',
          flexWrap: 'wrap',
          marginBottom: 'clamp(24px, 4vw, 40px)'
        }}>
          {categories.map((category) => (
            <button
              key={category}
              onClick={() => setSelectedCategory(category)}
              style={{
                backgroundColor: selectedCategory === category ? '#02042d' : 'transparent',
                color: selectedCategory === category ? '#ffffff' : '#02042d',
                border: '1px solid #02042d',
                borderRadius: '0px',
                padding: '8px 20px',
                fontFamily: 'Uxum Grotesque Regular, sans-serif',
                fontSize: '13px',
                cursor: 'pointer',
                transition: 'all 0.3s ease'
              }}
            >
              {category}
            </button>
          ))}
        </div>

        {/* Divider */}
        <div style={{
          width: '100%',
          height: '1px',
          backgroundColor: '#02042d',
          opacity: 0.15,
          marginBottom: 'clamp(32px, 4vw, 56px)'
        }} />

        {/* Cards Grid */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 380px), 1fr))',
          gap: 'clamp(16px, 2vw, 32px)'
        }}>
          {filteredPosts.length > 0 ? (
            filteredPosts.map((post, index) => (
              <BlogCard key={post.id} post={post} style={{ opacity: 0, transform: 'translateY(30px)' }} />
            ))
          ) : (
            <div style={{
              gridColumn: '1 / -1',
              padding: '80px 0',
              textAlign: 'center',
              fontFamily: 'Uxum Grotesque Regular, sans-serif',
              fontSize: '18px',
              color: '#555555'
            }}>
              No articles found in this category.
            </div>
          )}
        </div>

      </div>
    </section>
  );
}
